"""Self-contained, local-only trace viewer; requestAnimationFrame pacing."""

from __future__ import annotations

import json
from pathlib import Path

from .artifacts import atomic_write

TEMPLATE = "<!doctype html><html lang=\"zh-CN\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>ISAC World Model · v0.4 回放</title>\n<style>:root{font-family:system-ui;color:#162936;background:#edf1f4}*{box-sizing:border-box}body{max-width:1240px;margin:28px auto;padding:0 20px}h1{font-size:28px;margin-bottom:8px}p,small{line-height:1.6}.bar,.panel,.card{background:white;border:1px solid #d5dfe6;border-radius:12px;padding:16px;margin:14px 0}.bar{display:flex;align-items:center;gap:12px;flex-wrap:wrap}button,select{font:inherit;border:1px solid #bccad4;padding:7px 10px;border-radius:6px;background:#fff}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #3385af}#panel{display:grid;grid-template-columns:1.2fr 1fr;gap:20px}canvas{display:block;width:100%;background:#fff}#slider{flex:1;min-width:220px}.kv{display:grid;grid-template-columns:1fr 1fr;gap:9px}.kv span{padding:10px;background:#f3f6f8;border-radius:6px}strong{font-variant-numeric:tabular-nums}#status{font-weight:700;padding:12px;border-radius:8px;background:#fff0d6}table{border-collapse:collapse;width:100%;font-size:14px}th,td{padding:9px;border-bottom:1px solid #e1e6eb;text-align:left;font-variant-numeric:tabular-nums}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}small{color:#526775}@media(max-width:760px){#panel{grid-template-columns:1fr}body{padding:0 10px}.card{overflow:auto}}</style>\n<h1>ISAC World Model · v0.4</h1><p>从零训练 · 异步证据 · 独立测试回放</p>\n<small>合成场景研究原型。虚线为仅供评价的真值，实线为估计；监测状态不是物理安全认证。无外部服务、无联网请求。</small>\n<div class=\"bar\"><label>实验 <select id=\"run\"></select></label><button id=\"play\" aria-label=\"开始或暂停回放\">播放</button><button id=\"reset\">归零</button><label>速度 <select id=\"speed\"><option value=\".5\">0.5×</option><option value=\"1\" selected>1×</option><option value=\"2\">2×</option><option value=\"4\">4×</option></select></label><input aria-label=\"回放时间\" id=\"slider\" type=\"range\" min=\"0\" value=\"0\"><strong id=\"clock\"></strong></div>\n<div id=\"panel\" class=\"panel\"><div><canvas id=\"scene\" width=\"640\" height=\"600\"></canvas><canvas id=\"errors\" width=\"640\" height=\"130\"></canvas></div><div><div id=\"status\"></div><div id=\"stats\" class=\"kv\"></div><h3>当前证据与决策</h3><pre id=\"detail\"></pre><small>空格播放／暂停；左右箭头逐帧。播放采用浏览器刷新时钟与记录时间，不改变原始结果。</small></div></div>\n<div class=\"card\"><h2>独立测试汇总</h2><table id=\"summary\"></table></div><div class=\"card\"><h2>验证范围</h2><pre id=\"limitations\"></pre></div>\n<script>\nconst D=__PAYLOAD__, $=id=>document.getElementById(id),sel=$('run'),slider=$('slider'),canvas=$('scene'),ctx=canvas.getContext('2d'),ec=$('errors').getContext('2d');\nlet playing=false, accumulator=0, previous=0, dirty=true, frame=0, paths=[];\nD.runs.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=`${r.estimator} / ${r.policy} · seed ${r.seed}`;sel.append(o)});\nconst point=(s)=>[35+s[0]/D.scene.room_m*550,565-s[1]/D.scene.room_m*530];\nfunction prepare(){const r=D.runs[+sel.value];frame=0;slider.value=0;slider.max=r.trace.length-1;accumulator=0;paths=['truth','estimate'].map(key=>r.trace.map(row=>point(row[key])));dirty=true}\nfunction stat(label,value){const s=document.createElement('span');s.append(document.createTextNode(label+'\xa0'));const b=document.createElement('strong');b.textContent=value;s.append(b);return s}\nfunction draw(){const r=D.runs[+sel.value],v=r.trace[frame];slider.value=frame;ctx.clearRect(0,0,640,600);ctx.lineWidth=1;ctx.strokeStyle='#d8e1e7';ctx.strokeRect(35,35,550,530);for(let i=1;i<5;i++){ctx.beginPath();ctx.moveTo(35+i*110,35);ctx.lineTo(35+i*110,565);ctx.stroke()}\npaths.forEach((arr,index)=>{ctx.strokeStyle=index?'#14748f':'#5d6a74';ctx.fillStyle=ctx.strokeStyle;ctx.setLineDash(index?[]:[6,5]);ctx.lineWidth=2;ctx.beginPath();for(let k=0;k<=frame;k++){const [x,y]=arr[k];k?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(arr[frame][0],arr[frame][1],5,0,2*Math.PI);ctx.fill()});\nconst [x,y]=paths[1][frame];const rad=v.radius_m??v.heuristic_radius_m;if(Number.isFinite(rad)){ctx.strokeStyle=v.accepted?'#14748f':'#b67a28';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(x,y,Math.min(550,rad/D.scene.room_m*550),Math.min(530,rad/D.scene.room_m*530),0,0,Math.PI*2);ctx.stroke()}ctx.fillStyle='#263f50';ctx.font='14px system-ui';ctx.fillText('虚线：真值（仅评价）   实线：估计   圈：监测半径',35,20);\n$('clock').textContent=`${v.time_s.toFixed(2)} s / ${r.trace.at(-1).time_s.toFixed(2)} s`;\n$('status').textContent=(v.accepted?'可接受估计 · ':'未接受 · ')+(v.status||'legacy');$('status').style.background=v.accepted?'#def0e9':'#fff0d6';\n$('stats').replaceChildren(stat('位置误差',v.error_m.toFixed(3)+' m'),stat('计算时间',(v.compute_s*1000).toFixed(2)+' ms'),stat('测量操作',['跳过','快速','精细'][v.action]),stat('待交付观测',String(v.queue_depth)),stat('预算余额',(v.budget_tokens??0).toFixed(2)),stat('当前半径',Number.isFinite(rad)?rad.toFixed(3)+' m':'无效'));\n$('detail').textContent=JSON.stringify({runtime:D.runtime,output_available:v.output_available,output_input_cutoff_s:v.output_input_cutoff_s,output_ready_s:v.output_ready_s,output_state_time_s:v.output_state_time_s,new_output:v.new_output,busy_at_tick:v.busy_at_tick,information_age_s:v.age_s,valid:v.valid,arrived_ids:v.arrived_ids,overflow_dropped_ids:v.overflow_dropped_ids,requested_action:v.requested_action,communication_bits_proxy:v.communication_bits_proxy},null,2);\nec.clearRect(0,0,640,130);const max=Math.max(1,...r.trace.map(x=>x.error_m));ec.strokeStyle='#14748f';ec.beginPath();r.trace.forEach((z,i)=>{let px=35+i/(r.trace.length-1)*550,py=110-z.error_m/max*85;i?ec.lineTo(px,py):ec.moveTo(px,py)});ec.stroke();ec.strokeStyle='#b67a28';ec.beginPath();ec.moveTo(35+frame/(r.trace.length-1)*550,15);ec.lineTo(35+frame/(r.trace.length-1)*550,115);ec.stroke();ec.fillStyle='#526775';ec.fillText('位置误差曲线 · 上限 '+max.toFixed(2)+' m',35,12);dirty=false}\nfunction toggle(){playing=!playing;$('play').textContent=playing?'暂停':'播放';accumulator=0}\nsel.onchange=prepare;slider.oninput=()=>{frame=+slider.value;dirty=true;accumulator=0};$('reset').onclick=prepare;$('play').onclick=toggle;\ndocument.addEventListener('keydown',e=>{if(['INPUT','SELECT','BUTTON'].includes(e.target.tagName))return;if(e.code==='Space'){e.preventDefault();toggle()}if(e.code==='ArrowRight'||e.code==='ArrowLeft'){e.preventDefault();frame=Math.max(0,Math.min(+slider.max,frame+(e.code==='ArrowRight'?1:-1)));dirty=true}});\ndocument.addEventListener('visibilitychange',()=>{previous=0;accumulator=0});\nfunction tick(ts){const delta=previous?Math.min(250,ts-previous):0;previous=ts;if(playing&&!document.hidden){accumulator+=delta*Number($('speed').value);const r=D.runs[+sel.value];while(frame<r.trace.length-1){let duration=Math.max(1,(r.trace[frame+1].time_s-r.trace[frame].time_s)*1000);if(accumulator<duration)break;accumulator-=duration;frame++;dirty=true}if(frame===r.trace.length-1){playing=false;$('play').textContent='播放';accumulator=0}}if(dirty)draw();requestAnimationFrame(tick)}\nconst headings=['方法','RMSE / m','p95 / m','p95计算 / ms','感知占比','接受比例'];let tr=document.createElement('tr');headings.forEach(h=>{let t=document.createElement('th');t.textContent=h;tr.append(t)});$('summary').append(tr);\nObject.entries(D.summary).forEach(([name,m])=>{let row=document.createElement('tr');[name,...['position_rmse_m','position_p95_m','compute_p95_ms','sensing_airtime_fraction','acceptance_fraction'].map(k=>m[k]==null?'—':m[k].toFixed(3))].forEach(v=>{let t=document.createElement('td');t.textContent=v;row.append(t)});$('summary').append(row)});$('limitations').textContent=D.limitations.join('\\n');prepare();requestAnimationFrame(tick);\n</script></html>"


def write_viewer(report: dict, destination: Path) -> None:
    if not report.get("runs") or any(not r.get("trace") for r in report["runs"]):
        raise ValueError("Viewer requires nonempty traces")
    payload = json.dumps(report, allow_nan=False).replace("<", "\\u003c").replace("&", "\\u0026")
    atomic_write(destination, TEMPLATE.replace("__PAYLOAD__", payload).encode("utf-8"))
